 texts=[dict(t="课文一", narr=True, lines=[("","马丁有一个中国朋友下个星期结婚，马丁想送他一份礼物，但是不知道送什么合适。","Mǎdīng yǒu yí ge Zhōngguó péngyou xià ge xīngqī jié hūn, Mǎdīng xiǎng sòng tā yí fèn lǐwù, dànshì bù zhīdào sòng shénme héshì.","Martin có một người bạn Trung Quốc tuần sau kết hôn, Martin muốn tặng anh ấy một món quà, nhưng không biết tặng gì cho phù hợp."),
    ("","他问了不少中国人，他们都说：“你应该问你朋友喜欢什么，想要什么。”","Tā wènle bù shǎo Zhōngguó rén, tāmen dōu shuō: “Nǐ yīnggāi wèn nǐ péngyou xǐhuan shénme, xiǎng yào shénme.”","Anh ấy hỏi không ít người Trung Quốc, họ đều nói: “Bạn nên hỏi bạn mình thích gì, muốn gì.”"),
    ("","马丁去问朋友，他说：“我不需要你送我礼物，我希望你来参加我的婚礼。”","Mǎdīng qù wèn péngyou, tā shuō: “Wǒ bù xūyào nǐ sòng wǒ lǐwù, wǒ xīwàng nǐ lái cānjiā wǒ de hūnlǐ.”","Martin đi hỏi bạn, anh ấy nói: “Mình không cần bạn tặng quà, mình mong bạn đến dự đám cưới của mình.”"),
    ("","可是马丁觉得这么重要的事情，还是应该送一份特殊的礼物。","Kěshì Mǎdīng juéde zhème zhòngyào de shìqing, háishi yīnggāi sòng yí fèn tèshū de lǐwù.","Nhưng Martin cảm thấy chuyện quan trọng như vậy thì vẫn nên tặng một món quà đặc biệt.")],
    q=[("马丁的中国朋友什么时候结婚？","Mǎdīng de Zhōngguó péngyou shénme shíhou jié hūn?","下个星期。","Tuần sau."),("马丁知道他朋友想要什么礼物吗？","Mǎdīng zhīdào tā péngyou xiǎng yào shénme lǐwù ma?","不知道，朋友说不需要礼物。","Không biết, bạn nói không cần quà.")]),
  dict(t="课文二", lines=[("崔浩","你的中国朋友结婚，你准备了什么礼物？","Nǐ de Zhōngguó péngyou jié hūn, nǐ zhǔnbèile shénme lǐwù?","Bạn Trung Quốc của bạn kết hôn, bạn chuẩn bị quà gì?"),("马丁","到时候，我帮他们照相，然后送他们照片。","Dào shíhou, wǒ bāng tāmen zhào xiàng, ránhòu sòng tāmen zhàopiàn.","Đến lúc đó, mình chụp ảnh cho họ, sau đó tặng họ ảnh."),
    ("崔浩","你的礼物很有意思，你朋友一定喜欢。","Nǐ de lǐwù hěn yǒu yìsi, nǐ péngyou yídìng xǐhuan.","Quà của bạn rất thú vị, bạn của bạn nhất định sẽ thích."),("马丁","韩国人结婚的时候，你们一般送什么呢？","Hánguó rén jié hūn de shíhou, nǐmen yìbān sòng shénme ne?","Người Hàn kết hôn thì các bạn thường tặng gì?"),
    ("崔浩","亲戚、朋友常常送钱，他们觉得买东西太麻烦，给钱简单。","Qīnqi, péngyou chángcháng sòng qián, tāmen juéde mǎi dōngxi tài máfan, gěi qián jiǎndān.","Họ hàng, bạn bè thường tặng tiền, họ thấy mua đồ phiền quá, cho tiền thì đơn giản."),("马丁","这个办法也很好。","Zhège bànfǎ yě hěn hǎo.","Cách này cũng hay đấy.")],
    q=[("马丁准备了什么礼物？","Mǎdīng zhǔnbèile shénme lǐwù?","帮朋友照相，然后送他们照片。","Chụp ảnh cho bạn rồi tặng ảnh."),("结婚的时候，韩国人一般送什么礼物？","Jié hūn de shíhou, Hánguó rén yìbān sòng shénme lǐwù?","常常送钱。","Thường tặng tiền.")]),
  dict(t="课文三", lines=[("马丁","朱云，中国人一般什么时候送礼物？","Zhū Yún, Zhōngguó rén yìbān shénme shíhou sòng lǐwù?","Chu Vân, người Trung Quốc thường tặng quà khi nào?"),
    ("朱云","节日或者亲戚、朋友过生日、结婚的时候，中国人一般都要送礼物。","Jiérì huòzhě qīnqi, péngyou guò shēngrì, jié hūn de shíhou, Zhōngguó rén yìbān dōu yào sòng lǐwù.","Vào ngày lễ hoặc khi họ hàng, bạn bè sinh nhật, kết hôn, người Trung Quốc thường đều tặng quà."),
    ("马丁","我现在要去朋友家，要带礼物吗？","Wǒ xiànzài yào qù péngyou jiā, yào dài lǐwù ma?","Bây giờ mình định đến nhà bạn, có cần mang quà không?"),("朱云","不带礼物也可以。","Bú dài lǐwù yě kěyǐ.","Không mang quà cũng được."),
    ("马丁","我觉得还是带点儿东西比较好，我应该带什么呢？","Wǒ juéde háishi dài diǎnr dōngxi bǐjiào hǎo, wǒ yīnggāi dài shénme ne?","Mình thấy vẫn nên mang chút gì đó thì hơn, mình nên mang gì nhỉ?"),("朱云","你可以带一点儿水果，也可以带一束花。","Nǐ kěyǐ dài yìdiǎnr shuǐguǒ, yě kěyǐ dài yí shù huā.","Bạn có thể mang chút hoa quả, cũng có thể mang một bó hoa."),
    ("马丁","带好吃的东西或者酒，可以吗？","Dài hǎochī de dōngxi huòzhě jiǔ, kěyǐ ma?","Mang đồ ăn ngon hoặc rượu được không?"),("朱云","当然可以。","Dāngrán kěyǐ.","Đương nhiên là được.")],
    q=[("中国人一般什么时候送礼物？","Zhōngguó rén yìbān shénme shíhou sòng lǐwù?","节日或者亲戚、朋友过生日、结婚的时候。","Ngày lễ hoặc khi người thân, bạn bè sinh nhật, kết hôn."),("马丁觉得去朋友家不带礼物好不好？","Mǎdīng juéde qù péngyou jiā bú dài lǐwù hǎo bu hǎo?","他觉得还是带点儿东西比较好。","Anh ấy thấy vẫn nên mang chút gì thì hơn."),
       ("朱云说去朋友家可以带什么东西？","Zhū Yún shuō qù péngyou jiā kěyǐ dài shénme dōngxi?","水果、花、好吃的东西或者酒。","Hoa quả, hoa, đồ ăn ngon hoặc rượu.")])],
 bank=[("他送我一束花。","Tā sòng wǒ yí shù huā.","Anh ấy tặng tôi một bó hoa."),("我给他一点儿钱。","Wǒ gěi tā yìdiǎnr qián.","Tôi đưa anh ấy một ít tiền."),("去看朋友要带一点儿东西。","Qù kàn péngyou yào dài yìdiǎnr dōngxi.","Đi thăm bạn nên mang chút gì đó."),
  ("你感冒了，要吃药。","Nǐ gǎnmào le, yào chī yào.","Bạn bị cảm rồi, phải uống thuốc."),("还是我跟他说吧。","Háishi wǒ gēn tā shuō ba.","Hay là để tôi nói với anh ấy."),("你可以送水果，也可以送花儿。","Nǐ kěyǐ sòng shuǐguǒ, yě kěyǐ sòng huār.","Bạn có thể tặng hoa quả, cũng có thể tặng hoa.")],
