  ("个子","gèzi","dt","vóc dáng, chiều cao",("他个子很高。","Tā gèzi hěn gāo.","Anh ấy rất cao.")),("头发","tóufa","dt","tóc",("她头发很长。","Tā tóufa hěn cháng.","Tóc cô ấy rất dài.")),("眼睛","yǎnjing","dt","mắt",("她眼睛很大。","Tā yǎnjing hěn dà.","Mắt cô ấy rất to.")),
