 texts=[dict(t="课文一", narr=True, lines=[("","今天下午我们到李老师家做客。","Jīntiān xiàwǔ wǒmen dào Lǐ lǎoshī jiā zuò kè.","Chiều nay chúng tôi đến nhà thầy Lý chơi."),
    ("","李老师的爱人给我们做了很多好吃的菜，她还教我们包饺子。","Lǐ lǎoshī de àiren gěi wǒmen zuòle hěn duō hǎochī de cài, tā hái jiāo wǒmen bāo jiǎozi.","Vợ thầy Lý nấu cho chúng tôi rất nhiều món ngon, cô ấy còn dạy chúng tôi gói sủi cảo."),
    ("","李老师给我们买了葡萄酒和啤酒。大家一起喝酒、吃饭、聊天儿，非常高兴。","Lǐ lǎoshī gěi wǒmen mǎile pútaojiǔ hé píjiǔ. Dàjiā yìqǐ hē jiǔ, chī fàn, liáo tiānr, fēicháng gāoxìng.","Thầy Lý mua rượu vang và bia cho chúng tôi. Mọi người cùng uống rượu, ăn cơm, trò chuyện, rất vui."),
    ("","晚上十点，我们才回家。","Wǎnshang shí diǎn, wǒmen cái huí jiā.","Mười giờ tối chúng tôi mới về nhà.")],
    q=[("“我们”什么时候到李老师家做客的？","“Wǒmen” shénme shíhou dào Lǐ lǎoshī jiā zuò kè de?","今天下午。","Chiều nay."),("“我们”在李老师家做什么了？","“Wǒmen” zài Lǐ lǎoshī jiā zuò shénme le?","包饺子、喝酒、吃饭、聊天儿。","Gói sủi cảo, uống rượu, ăn cơm, trò chuyện.")]),
  dict(t="课文二", scene="学生们正在包饺子，这时候，李一民从外边回来了。", scene_vi="Các học sinh đang gói sủi cảo, lúc đó thầy Lý Nhất Dân từ ngoài về.", lines=[("李一民","这么热闹啊，大家都来了？","Zhème rènao a, dàjiā dōu lái le?","Náo nhiệt thế, mọi người đến cả rồi à?"),
    ("学生","李老师，我们四点半就到了。您去哪儿了？","Lǐ lǎoshī, wǒmen sì diǎn bàn jiù dào le. Nín qù nǎr le?","Thầy Lý, bọn em bốn rưỡi đã đến rồi. Thầy đi đâu vậy ạ?"),
    ("李一民","我去超市买酒了。你们看，我买了一瓶葡萄酒，还买了十瓶啤酒。今天星期六，大家可以多喝一点儿。我最近身体不好，不能喝酒，我多说话。","Wǒ qù chāoshì mǎi jiǔ le. Nǐmen kàn, wǒ mǎile yì píng pútaojiǔ, hái mǎile shí píng píjiǔ. Jīntiān xīngqīliù, dàjiā kěyǐ duō hē yìdiǎnr. Wǒ zuìjìn shēntǐ bù hǎo, bù néng hē jiǔ, wǒ duō shuō huà.","Thầy đi siêu thị mua rượu. Các em xem, thầy mua một chai vang, còn mua mười chai bia. Hôm nay thứ Bảy, mọi người có thể uống nhiều một chút. Gần đây sức khỏe thầy không tốt, không uống được rượu, thầy sẽ nói chuyện nhiều."),
    ("林娜","李老师，这是我第一次包饺子，您看怎么样？","Lǐ lǎoshī, zhè shì wǒ dì-yī cì bāo jiǎozi, nín kàn zěnmeyàng?","Thầy Lý, đây là lần đầu em gói sủi cảo, thầy xem thế nào ạ?"),("李一民","非常好！你们觉得包饺子难学吗？","Fēicháng hǎo! Nǐmen juéde bāo jiǎozi nán xué ma?","Rất tốt! Các em thấy gói sủi cảo có khó học không?"),
    ("林娜","不难学，可是准备包饺子很麻烦。","Bù nán xué, kěshì zhǔnbèi bāo jiǎozi hěn máfan.","Không khó học, nhưng chuẩn bị để gói thì rất phiền.")],
    q=[("李老师去超市买了什么东西？","Lǐ lǎoshī qù chāoshì mǎile shénme dōngxi?","一瓶葡萄酒和十瓶啤酒。","Một chai vang và mười chai bia."),("包饺子难学吗？","Bāo jiǎozi nán xué ma?","不难学，可是准备很麻烦。","Không khó, nhưng chuẩn bị rất phiền.")]),
  dict(t="课文三", lines=[("林娜","李老师，您觉得我们汉语有进步吗？","Lǐ lǎoshī, nín juéde wǒmen Hànyǔ yǒu jìnbù ma?","Thầy Lý, thầy thấy tiếng Hán của bọn em có tiến bộ không ạ?"),("李一民","你们这么努力学习，当然有进步了。","Nǐmen zhème nǔlì xuéxí, dāngrán yǒu jìnbù le.","Các em học chăm như vậy, đương nhiên là có tiến bộ."),
    ("山田","我汉字没有问题，可是我发音不好。","Wǒ Hànzì méiyǒu wèntí, kěshì wǒ fāyīn bù hǎo.","Chữ Hán của em không có vấn đề, nhưng phát âm của em không tốt."),("马丁","我口语和听力都很好，汉字也认识，但是不会写。","Wǒ kǒuyǔ hé tīnglì dōu hěn hǎo, Hànzì yě rènshi, dànshì bú huì xiě.","Khẩu ngữ và nghe của em đều tốt, chữ Hán cũng nhận ra, nhưng không biết viết."),
    ("林娜","我的声调总是不好，应该怎么办呢？","Wǒ de shēngdiào zǒngshì bù hǎo, yīnggāi zěnme bàn ne?","Thanh điệu của em lúc nào cũng không tốt, nên làm thế nào ạ?"),
    ("李一民","别着急，你们平时多听、多说、多看、多写，进步一定更快。好，我们别说学习了，快来吃饭吧！","Bié zháojí, nǐmen píngshí duō tīng, duō shuō, duō kàn, duō xiě, jìnbù yídìng gèng kuài. Hǎo, wǒmen bié shuō xuéxí le, kuài lái chī fàn ba!","Đừng lo, ngày thường các em nghe nhiều, nói nhiều, đọc nhiều, viết nhiều thì nhất định tiến bộ nhanh hơn. Thôi, chúng ta đừng nói chuyện học nữa, mau đến ăn cơm đi!")],
    q=[("山田汉语有什么问题？","Shāntián Hànyǔ yǒu shénme wèntí?","发音不好。","Phát âm không tốt."),("马丁汉语怎么样？","Mǎdīng Hànyǔ zěnmeyàng?","口语和听力都很好，但是不会写汉字。","Nói và nghe đều tốt, nhưng không biết viết chữ Hán."),("林娜汉语有什么问题？","Línnà Hànyǔ yǒu shénme wèntí?","声调总是不好。","Thanh điệu luôn không tốt.")])],
